// Two zones of 274 x 283, one on each side of the halfway line (Z = 0)
CMND_BTL_REGIST_FLOOR_ATTR("FL01", -137, 0, 274, 283);
CMND_BTL_REGIST_FLOOR_ATTR("FL02", -137, -283, 274, 283);

// mapFloorAttr[idx] holds one [x, z, width, depth] entry per zone.
// Every zone gets attribute 5, then the pitch-down event starts.
ScMapPitchDown <- function ( idx )
{
	for( local i = 0; i < mapFloorAttr[idx].len(); i++ )
	{
		CMND_BTL_REGIST_FLOOR_ATTR(mapFloorAttrName[i], mapFloorAttr[idx][i][0], mapFloorAttr[idx][i][1], mapFloorAttr[idx][i][2], mapFloorAttr[idx][i][3]);
		CMND_BTL_ADD_FLOOR_ATTR(mapFloorAttrName[i], 5);
	}

	CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_PITCHDOWN, idx + 1);
};
